\\\\\n    const match = f.match(/tests\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\/test_([a-z_]+)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\.py$/i);\\\\\\\\\\\\\\\\n    if (match) {\\\\\\\\\\\\\\\\n      const moduleParts = match[1].toLowerCase().split('_');\\\\\\\\\\\\\\\\n      // Add both singular and plural forms, plus the full module name\\\\\\\\\\\\\\\\n      const modules = [...moduleParts];\\\\\\\\\\\\\\\\n      moduleParts.forEach(p => {\\\\\\\\\\\\\\\\n        if (!p.endsWith('s')) modules.push(p + 's');\\\\\\\\\\\\\\\\n        if (p.endsWith('s')) modules.push(p.slice(0, -1));\\\\\\\\\\\\\\\\n      });\\\\\\\\\\\\\\\\n      modules.push(match[1]); // full module name like \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"adapter_base\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n      testFileModules.set(f, modules);\\\\\\\\\\\\\\\\n    }\\\\\\\\\\\\\\\\n  });\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n  // Match tasks to commits/files\\\\\\\\\\\\\\\\n  for (const task of taskLines) {\\\\\\\\\\\\\\\\n    const taskLower = task.toLowerCase();\\\\\\\\\\\\\\\\n    const taskWords = taskLower.match(/\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\b[a-z_-]{3,}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\b/g) || [];\\\\\\\\\\\\\\\\n    const isTestTask = /\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\b(test|tests|unit\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\s*test|coverage)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\b/i.test(task);\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    // Calculate overlap score using expanded keywords (with synonyms)\\\\\\\\\\\\\\\\n    const matchingWords = taskWords.filter(w => expandedKeywords.has(w));\\\\\\\\\\\\\\\\n    const score = taskWords.length > 0 ? matchingWords.length / taskWords.length : 0;\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    // Extract explicit file references from task (e.g., `filename.js` or filename.test.js)\\\\\\\\\\\\\\\\n    const fileRefs = taskLower.match(/`([^`]+\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\.[a-z]+)`|([a-z0-9_./-]+(?:\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\.test)?\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\.(?:js|ts|py|yml|yaml|md))/g) || [];