al match)\\\\\\\\\\\\\\\\n    const fileMatch = filesChanged.some(f => {\\\\\\\\\\\\\\\\n      const fLower = f.toLowerCase();\\\\\\\\\\\\\\\\n      return taskWords.some(w => fLower.includes(w));\\\\\\\\\\\\\\\\n    });\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    // Check for specific commit message matches\\\\\\\\\\\\\\\\n    const commitMatch = commits.some(c => {\\\\\\\\\\\\\\\\n      const msg = c.commit.message.toLowerCase();\\\\\\\\\\\\\\\\n      return taskWords.some(w => w.length > 4 && msg.includes(w));\\\\\\\\\\\\\\\\n    });\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    let confidence = 'low';\\\\\\\\\\\\\\\\n    let reason = '';\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    // Exact file match is very high confidence\\\\\\\\\\\\\\\\n    if (exactFileMatch) {\\\\\\\\\\\\\\\\n      confidence = 'high';\\\\\\\\\\\\\\\\n      const matchedFile = cleanFileRefs.find(ref => filesChanged.some(f => f.toLowerCase().includes(ref)));\\\\\\\\\\\\\\\\n      reason = `Exact file created: ${matchedFile}`;\\\\\\\\\\\\\\\\n      matches.push({ task, reason, confidence });\\\\\\\\\\\\\\\\n    } else if (isTestTask && testModuleMatch) {\\\\\\\\\\\\\\\\n      confidence = 'high';\\\\\\\\\\\\\\\\n      reason = 'Test file created matching module reference';\\\\\\\\\\\\\\\\n      matches.push({ task, reason, confidence });\\\\\\\\\\\\\\\\n    } else if (score >= 0.35 && (fileMatch || commitMatch)) {\\\\\\\\\\\\\\\\n      // Lowered threshold from 0.5 to 0.35 to catch more legitimate completions\\\\\\\\\\\\\\\\n      confidence = 'high';\\\\\\\\\\\\\\\\n      reason = `${Math.round(score * 100)}% keyword match, ${fileMatch ? 'file match' : 'commit match'}`;\\\\\\\\\\\\\\\\n      matches.push({ task, reason, confidence });\\\\\\\\\\\\\\\\n    } else if (score >= 0.25 && fileMatch) {\\\\\\\\\\\\\\\\n      // File match with moderate keyword overlap is high confidence\\\\\\\\\\\\\\\\n      confidence = 'high';\\\\\\\\\\\\\\\\n      reason = `${Math.round(score * 100)}% keyword match with file match`;\\\\